session_start();include('check-login.php');include('dbstring.php');include_once('department-result-workflow-utils.php');
if(!drw_is_admin()){http_response_code(403);exit('Administrator access required.');}drw_ensure_tables($con);$msg='';$user=isset($_SESSION['USERID'])?$_SESSION['USERID']:'';
if(isset($_POST['create_department'])){$name=trim((string)$_POST['departmentname']);$hod=trim((string)$_POST['hodid']);if($name===''||$hod==='')$msg='Enter a department name and choose its HOD.';else{$id=drw_id('DEP_');$n=mysqli_real_escape_string($con,$name);$h=mysqli_real_escape_string($con,$hod);$u=mysqli_real_escape_string($con,$user);$ok=mysqli_query($con,"INSERT INTO tbldepartment(departmentid,departmentname,hodid,status,createdby,createdat,updatedat) VALUES('$id','$n','$h','active','$u',NOW(),NOW())");if($ok){mysqli_query($con,"INSERT IGNORE INTO tbldepartmentteacher(departmentid,teacherid,assignedat,assignedby) VALUES('$id','$h',NOW(),'$u')");$msg='Department created and HOD assigned.';}else $msg='That department name already exists.';}}
if(isset($_POST['assign_teacher'])){$d=mysqli_real_escape_string($con,$_POST['departmentid']);$t=mysqli_real_escape_string($con,$_POST['teacherid']);$u=mysqli_real_escape_string($con,$user);mysqli_query($con,"INSERT IGNORE INTO tbldepartmentteacher(departmentid,teacherid,assignedat,assignedby) VALUES('$d','$t',NOW(),'$u')");$msg='Teacher assigned to department.';}
if(isset($_POST['assign_subject'])){$d=mysqli_real_escape_string($con,$_POST['departmentid']);$s=mysqli_real_escape_string($con,$_POST['classificationid']);$u=mysqli_real_escape_string($con,$user);mysqli_query($con,"INSERT IGNORE INTO tbldepartmentsubject(departmentid,classificationid,assignedat,assignedby) VALUES('$d','$s',NOW(),'$u')");$msg='Subject assigned to department.';}
$teachers=array();$r=mysqli_query($con,"SELECT userid,firstname,othernames,surname FROM tblsystemuser WHERE systemtype='Teacher' AND status='active' ORDER BY firstname,surname");if($r)while($x=mysqli_fetch_assoc($r))$teachers[]=$x;$deps=array();$r=mysqli_query($con,"SELECT d.*,CONCAT_WS(' ',u.firstname,u.othernames,u.surname) hodname,(SELECT COUNT(*) FROM tbldepartmentteacher dt WHERE dt.departmentid=d.departmentid) teacher_count,(SELECT COUNT(*) FROM tbldepartmentsubject ds WHERE ds.departmentid=d.departmentid) subject_count FROM tbldepartment d LEFT JOIN tblsystemuser u ON u.userid=d.hodid WHERE d.status='active' ORDER BY d.departmentname");if($r)while($x=mysqli_fetch_assoc($r))$deps[]=$x;$subjects=array();$r=mysqli_query($con,"SELECT sc.classificationid,sub.subject,ce.class_name FROM tblsubjectclassification sc INNER JOIN tblsubject sub ON sub.subjectid=sc.subjectid LEFT JOIN tblclassentry ce ON ce.class_entryid=sc.classid ORDER BY sub.subject,ce.class_name");if($r)while($x=mysqli_fetch_assoc($r))$subjects[]=$x;
function dm($x){return htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8');}
