<script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.dm select').forEach(function(s){var w=document.createElement('div'),b=document.createElement('button'),l=document.createElement('div');w.className='dm-cs';b.type='button';b.className='dm-cs-btn';l.className='dm-cs-list';function r(){b.textContent=s.options[s.selectedIndex]?s.options[s.selectedIndex].text:'Select';Array.prototype.forEach.call(l.children,function(x){x.classList.toggle('selected',x.dataset.v===s.value);});}Array.prototype.forEach.call(s.options,function(o){var x=document.createElement('button');x.type='button';x.className='dm-cs-opt';x.dataset.v=o.value;x.textContent=o.text;x.onclick=function(){s.value=o.value;r();w.classList.remove('open');s.dispatchEvent(new Event('change',{bubbles:true}));};l.appendChild(x);});b.onclick=function(){document.querySelectorAll('.dm-cs.open').forEach(function(x){if(x!==w)x.classList.remove('open');});w.classList.toggle('open');};s.parentNode.insertBefore(w,s);w.appendChild(b);w.appendChild(l);s.style.display='none';w.appendChild(s);r();});document.addEventListener('click',function(e){if(!e.target.closest('.dm-cs'))document.querySelectorAll('.dm-cs.open').forEach(function(x){x.classList.remove('open');});});});</script>
<!doctype html><html><head><?php include('links.php');?><title>Department & HOD Setup</title><style>body{background:#f4f8fb;font-family:Arial;color:#17314b}.dm{max-width:1100px;margin:28px auto;background:#fff;padding:25px;border-radius:16px}.dm-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.dm section{border:1px solid #dbe6ee;border-radius:12px;padding:16px}.dm input,.dm select{width:100%;box-sizing:border-box;padding:10px;color:#102a43!important;background:#fff!important;border:1px solid #8ca4b7;border-radius:7px}.dm button{margin-top:12px;background:#087443;color:white;border:0;border-radius:8px;padding:11px 14px;font-weight:bold}.dm table{width:100%;border-collapse:collapse;margin-top:20px}.dm td,.dm th{padding:10px;border-bottom:1px solid #dbe6ee;text-align:left}@media(max-width:760px){.dm-grid{grid-template-columns:1fr}.dm{margin:10px}}</style></head><body><main class="dm"><h1>Departments, HODs & Subjects</h1><p>Set the departments first. Only subjects mapped here will be routed through HOD and Academic approval.</p><?php if($msg!=='')echo '<p>'.dm($msg).'</p>';?><div class="dm-grid"><section><h2>Create Department</h2><form method="post"><input name="departmentname" placeholder="Department name" required><p><select name="hodid" required><option value="">Choose HOD</option><?php foreach($teachers as $t){?><option value="<?php echo dm($t['userid']);?>"><?php echo dm($t['firstname'].' '.$t['othernames'].' '.$t['surname']);?></option><?php }?></select></p><button name="create_department">Create Department</button></form></section><section><h2>Assign Teacher</h2><form method="post"><select name="departmentid" required><option value="">Choose department</option><?php foreach($deps as $d){?><option value="<?php echo dm($d['departmentid']);?>"><?php echo dm($d['departmentname']);?></option><?php }?></select><p><select name="teacherid" required><option value="">Choose teacher</option><?php foreach($teachers as $t){?><option value="<?php echo dm($t['userid']);?>"><?php echo dm($t['firstname'].' '.$t['othernames'].' '.$t['surname']);?></option><?php }?></select></p><button name="assign_teacher">Assign Teacher</button></form></section><section><h2>Assign Subject</h2><form method="post"><select name="departmentid" required><option value="">Choose department</option><?php foreach($deps as $d){?><option value="<?php echo dm($d['departmentid']);?>"><?php echo dm($d['departmentname']);?></option><?php }?></select><p><select name="classificationid" required><option value="">Choose subject</option><?php foreach($subjects as $s){?><option value="<?php echo dm($s['classificationid']);?>"><?php echo dm($s['subject'].' — '.$s['class_name']);?></option><?php }?></select></p><button name="assign_subject">Assign Subject</button></form></section></div><h2>Current Departments</h2><table><tr><th>Department</th><th>HOD</th><th>Teachers</th><th>Subjects</th></tr><?php foreach($deps as $d){?><tr><td><?php echo dm($d['departmentname']);?></td><td><?php echo dm($d['hodname']);?></td><td><?php echo (int)$d['teacher_count'];?></td><td><?php echo (int)$d['subject_count'];?></td></tr><?php }?></table></main></body></html>
